select exists (select 1 from pg_policies where schemaname='public' and tablename='student_groups' and policyname='student_groups_select' and qual like '%student_group_members%') and not has_table_privilege('anon','public.quiz_results','SELECT') and has_table_privilege('authenticated','public.quiz_results','SELECT') and not has_table_privilege('authenticated','public.chat_users','SELECT') as ok;
